/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, gt, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { InvalidSlugError, uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations, retiredOrganizationSlugs } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);
  const retired = getDb().select({ org: organizations })
    .from(retiredOrganizationSlugs)
    .innerJoin(organizations, eq(organizations.id, retiredOrganizationSlugs.orgId))
    .where(and(
      eq(retiredOrganizationSlugs.slug, slug),
      gt(retiredOrganizationSlugs.retiredAt, holdCutoff()),
      isNull(organizations.archivedAt),
    )).get();
  return retired ? toOrganization(retired.org) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

/** Settings and profile patch; URL changes use the retirement transaction. */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const held = getDb().select({ slug: retiredOrganizationSlugs.slug })
    .from(retiredOrganizationSlugs)
    .where(and(
      like(retiredOrganizationSlugs.slug, `${prefix}%`),
      gt(retiredOrganizationSlugs.retiredAt, holdCutoff()),
    )).all();
  return [...rows, ...held].map((row) => row.slug);
}

function holdCutoff(): string {
  return new Date(Date.now() - ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000).toISOString();
}

/** Availability and retirement are committed together, before publishing. */
export async function renameOrgSlug(orgId: OrgId, slug: string): Promise<{
  organization: Organization;
  from: string;
}> {
  return getDb().transaction((tx) => {
    const current = tx.select().from(organizations).where(eq(organizations.id, orgId)).get();
    if (!current) throw new Error(`Organization ${orgId} not found`);
    if (current.slug === slug) return { organization: toOrganization(current), from: slug };

    const taken = tx.select().from(organizations).where(eq(organizations.slug, slug)).get();
    const held = tx.select().from(retiredOrganizationSlugs).where(and(
      eq(retiredOrganizationSlugs.slug, slug),
      gt(retiredOrganizationSlugs.retiredAt, holdCutoff()),
    )).get();
    if ((taken && taken.id !== orgId) || (held && held.orgId !== orgId)) {
      throw new InvalidSlugError(slug, "is unavailable");
    }

    const stamp = toIsoTimestamp(new Date());
    tx.delete(retiredOrganizationSlugs).where(eq(retiredOrganizationSlugs.slug, slug)).run();
    tx.insert(retiredOrganizationSlugs).values({
      slug: current.slug, orgId, retiredAt: stamp,
    }).onConflictDoUpdate({
      target: retiredOrganizationSlugs.slug,
      set: { orgId, retiredAt: stamp },
    }).run();
    const row = tx.update(organizations).set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId)).returning().get();
    return { organization: toOrganization(row), from: current.slug };
  });
}
